#!/bin/sh
set -eu
losetup -o 77858865152 /dev/loop0 /dev/sdc
mount -t ext4 -o noatime /dev/loop0 /mnt/codex-ufs-root
R=/mnt/codex-ufs-root/openwrt
B=/mnt/codex-ufs-root/.changxing60/codex-backup-20261028
mkdir -p "$B" "$R/etc/dropbear" "$R/lib/firmware"
cp -p "$R/etc/init.d/changxing60-audio" "$B/changxing60-audio.before"
[ ! -f "$R/etc/dropbear/authorized_keys" ] || cp -p "$R/etc/dropbear/authorized_keys" "$B/authorized_keys.before"
: > /tmp/codex-stage.b64
printf %s  >> /tmp/codex-stage.b64
printf %s  >> /tmp/codex-stage.b64
printf %s  >> /tmp/codex-stage.b64
printf %s  >> /tmp/codex-stage.b64
printf %s  >> /tmp/codex-stage.b64
printf %s  >> /tmp/codex-stage.b64
base64 -d /tmp/codex-stage.b64 > /mnt/codex-ufs-root/openwrt/etc/init.d/changxing60-audio
: > /tmp/codex-stage.b64
printf %s  >> /tmp/codex-stage.b64
printf %s  >> /tmp/codex-stage.b64
printf %s  >> /tmp/codex-stage.b64
printf %s  >> /tmp/codex-stage.b64
printf %s  >> /tmp/codex-stage.b64
base64 -d /tmp/codex-stage.b64 > /mnt/codex-ufs-root/openwrt/opt/changxing60/bin/changxing60-fast-playback
: > /tmp/codex-stage.b64
printf %s c3NoLWVkMjU1MTkgQUFBQUMzTnphQzFsWkRJMU5URTVBQUFBSUhtSWxsSXorVUJWQVVUeDFvazdDc1VSYnZWVHpJckxWemp5SkFGVkFJVjQgY29kZXgtNzU1Mm4tMjAyNjEwMjgK >> /tmp/codex-stage.b64
base64 -d /tmp/codex-stage.b64 > /mnt/codex-ufs-root/openwrt/etc/dropbear/codex-7552n.pub
chmod 755 "$R/etc/init.d/changxing60-audio" "$R/opt/changxing60/bin/changxing60-fast-playback"
cat "$R/etc/dropbear/codex-7552n.pub" >> "$R/etc/dropbear/authorized_keys"
chmod 600 "$R/etc/dropbear/authorized_keys"
cp /lib/firmware/aw87xxx_acf.bin "$R/lib/firmware/aw87xxx_acf.bin"
sha256sum "$R/lib/firmware/aw87xxx_acf.bin" "$R/opt/changxing60/bin/changxing60-fast-playback"
sync
umount /mnt/codex-ufs-root
losetup -d /dev/loop0
echo ROOTFS_STAGE_OK
